const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".ft{display:flex;flex-direction:column;gap:6px;width:100%;height:100%;padding:10px;min-width:0;min-height:0;overflow:hidden;color:var(--ink);font-size:13px;line-height:1.35}\n.ft *{box-sizing:border-box}\n.ft button,.ft input{font:inherit;color:var(--ink)}\n.ft button{cursor:pointer}\n.ft.s-3x3{padding:8px;gap:5px;--rs:76px;--rw:7px;--tf:16px}\n.ft.s-6x3{--rs:124px;--rw:9px;--tf:24px}\n.ft.s-3x6{--rs:128px;--rw:10px;--tf:25px}\n.ft.s-6x6{padding:14px;gap:10px;--rs:164px;--rw:12px;--tf:32px}\n\n.top{display:flex;align-items:center;gap:6px;min-width:0;flex:none}\n.sp{flex:1 1 0;min-width:0}\n.pill{flex:0 1 auto;min-width:0;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:11px;font-weight:600;padding:3px 8px;border-radius:99px;background:var(--soft);color:var(--ink)}\n.pill::before{content:\"\";display:inline-block;width:6px;height:6px;margin-right:5px;border-radius:50%;background:var(--muted);vertical-align:middle}\n.ft.active .pill::before{background:var(--accent)}\n.ft.isbreak .pill::before{background:var(--accent-alt)}\n.ft.paused .pill::before{background:var(--muted)}\n.chip{flex:none;border:1px solid var(--line);background:transparent;border-radius:99px;font-size:11px;padding:3px 8px;white-space:nowrap}\n.stat{flex:none;font-size:11px;color:var(--muted);white-space:nowrap}\n.mini{flex:none;font-weight:700;font-variant-numeric:tabular-nums}\n\n.main{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;flex:1 1 auto;min-width:0;min-height:0}\n.ft.s-3x6 .main,.ft.s-6x6 .main{flex:none}\n.ft.s-6x3 .main,.ft.s-6x6 .main{flex-direction:row;gap:16px}\n.ringwrap{position:relative;flex:none;display:grid;place-items:center;width:var(--rs);height:var(--rs)}\n.ft.s-3x3.idle .ringwrap{display:none}\n.ring{position:absolute;inset:0;border-radius:50%;background:conic-gradient(var(--accent) calc(var(--p,0) * 1%),var(--soft) 0);-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - var(--rw)),var(--ink) calc(100% - var(--rw) + 1px));mask:radial-gradient(farthest-side,transparent calc(100% - var(--rw)),var(--ink) calc(100% - var(--rw) + 1px))}\n.ft.isbreak .ring{background:conic-gradient(var(--accent-alt) calc(var(--p,0) * 1%),var(--soft) 0)}\n.ft.paused .ring{opacity:.55}\n.tm{position:relative;font-size:var(--tf);font-weight:700;font-variant-numeric:tabular-nums;letter-spacing:.5px;white-space:nowrap}\n.tm.long{font-size:calc(var(--tf) * .8)}\n.ft.idle .tm{color:var(--muted)}\n\n.panel{display:flex;flex-direction:column;gap:6px;width:100%;min-width:0}\n.ft.s-6x3 .panel,.ft.s-6x6 .panel{flex:1 1 0}\n.act{display:flex;flex-direction:column;gap:2px;min-width:0}\n.nowl{font-size:11px;color:var(--muted)}\n.tk{font-weight:600;overflow-wrap:anywhere;max-height:3.9em;overflow-y:auto;min-width:0}\n.ft.s-3x3 .nowl{display:none}\n.ft.s-3x3 .tk{white-space:nowrap;overflow-x:auto;overflow-y:hidden;max-height:none;text-align:center;scrollbar-width:none;font-size:12px}\n.ft.s-3x3 .tk::-webkit-scrollbar{display:none}\n.ctl{display:flex;gap:6px;min-width:0}\n.hint{font-size:11px;color:var(--muted);text-align:center}\n.hint.left{text-align:left}\n.notice{font-size:11px;padding:4px 8px;border-radius:8px;background:var(--soft);color:var(--ink)}\n.err{font-size:11px;font-weight:600}\n.err:empty{display:none}\n\n.b{flex:1 1 0;min-width:0;height:32px;padding:0 10px;border-radius:10px;border:1px solid var(--line);background:var(--soft);color:var(--ink);font-weight:600;white-space:nowrap}\n.ft.s-3x3 .b{height:30px;padding:0 6px}\n.b.primary{background:var(--accent);border-color:transparent;color:var(--on-accent)}\n.task{width:100%;min-width:0;height:32px;padding:0 10px;border-radius:10px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink)}\n.ft.s-3x3 .task{height:30px}\n.task::placeholder{color:var(--muted)}\n.b:focus-visible,.sb:focus-visible,.chip:focus-visible,.num:focus-visible,.task:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.sec{display:flex;flex-direction:column;gap:6px;min-width:0;min-height:0}\n.ptitle{font-size:12px;font-weight:700}\n.row{display:flex;align-items:center;gap:6px;min-width:0}\n.lbl{flex:none;min-width:2.4em;font-size:12px;color:var(--muted)}\n.step{display:flex;align-items:center;gap:3px;min-width:0}\n.sb{flex:none;width:26px;height:28px;padding:0;border-radius:8px;border:1px solid var(--line);background:var(--soft);font-size:15px;line-height:1}\n.sb.wide{width:auto;min-width:34px;padding:0 6px;font-size:12px}\n.num{flex:none;width:40px;height:28px;padding:0 2px;text-align:center;border-radius:8px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);font-variant-numeric:tabular-nums}\n.unit{flex:none;font-size:11px;color:var(--muted);white-space:nowrap;margin-left:2px}\n\n.list{display:flex;flex-direction:column;flex:1 1 auto;min-height:0;overflow-y:auto}\n.li{display:flex;align-items:baseline;gap:8px;padding:5px 0;border-bottom:1px solid var(--line);min-width:0}\n.lt{flex:none;font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}\n.ln{flex:1 1 0;min-width:0;overflow-wrap:anywhere}\n.lm{flex:none;font-size:11px;color:var(--muted);white-space:nowrap}\n.empty{font-size:12px;color:var(--muted);padding:6px 0}\n\n.sub{display:flex;flex-direction:column;gap:8px;flex:1 1 auto;min-height:0}\n.sub > .sec{flex:1 1 auto;overflow-y:auto}\n.sub > .sec.log{overflow:hidden}\n\n.extra{flex:1 1 auto;min-height:0;display:flex;flex-direction:column;gap:12px;overflow-y:auto}\n.extra > .sec{flex:none}\n.ft.s-3x6 .extra .list{overflow:visible;flex:none}\n.ft.s-6x6 .extra{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:16px;overflow:hidden}\n.ft.s-6x6 .extra > .sec{overflow-y:auto}\n.ft.s-6x6 .extra > .sec.log{overflow:hidden}\n.ft.s-6x6 .extra .list{flex:1 1 0}\n";
const DEF_FOCUS = 25;
const DEF_BREAK = 5;

function clampInt(v, lo, hi, fb) {
  const n = Math.round(Number(v));
  if (!isFinite(n)) return fb;
  return Math.min(hi, Math.max(lo, n));
}

// 统一补全持久数据：设置默认值只在用户给出的 25/5 分钟；记录与计时器默认为空
function norm(s) {
  s = s || {};
  const st = s.settings || {};
  const t = s.timer && typeof s.timer === 'object' ? s.timer : null;
  return Object.assign({}, s, {
    settings: {
      focusMin: clampInt(st.focusMin, 1, 180, DEF_FOCUS),
      breakMin: clampInt(st.breakMin, 1, 60, DEF_BREAK)
    },
    rounds: Array.isArray(s.rounds) ? s.rounds : [],
    timer: t
  });
}

function initialize(s) {
  s = s || {};
  if (s.settings && Array.isArray(s.rounds) && 'timer' in s) return s;
  return norm(s);
}

function p2(n) {
  return n < 10 ? '0' + n : '' + n;
}

function dayOf(ts) {
  const d = new Date(ts);
  return d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate());
}

function hhmm(ts) {
  const d = new Date(ts);
  return p2(d.getHours()) + ':' + p2(d.getMinutes());
}

function mmss(sec) {
  sec = Math.max(0, Math.ceil(sec));
  return p2(Math.floor(sec / 60)) + ':' + p2(sec % 60);
}

// 剩余秒数：运行中按结束时间戳算（关闭再打开仍准确），暂停时用保存的剩余值
function leftSec(t, now) {
  if (!t) return 0;
  if (t.status === 'paused') return Math.max(0, t.remainSec || 0);
  return Math.max(0, (t.endAt - now) / 1000);
}


function mount(ctx) {
  const { root, el, state, ui, update, redraw, uid, day, size } = ctx;
  const S = norm(state);
  const T = S.timer;
  const st = S.settings;
  const roomy = size === '3x6' || size === '6x6';
  const view = roomy ? 'main' : (ui.view || 'main');
  const today = day();
  const todays = S.rounds.filter(r => r.day === today).sort((a, b) => b.doneAt - a.doneAt);
  const todayMin = todays.reduce((a, r) => a + (r.minutes || 0), 0);
  let timeEl = null, ringEl = null, errEl = null;
  let iv = null, t0 = null, ct = null;
  if (ui.confirm && !(T && T.phase === 'focus')) ui.confirm = false;

  function setUi(patch) {
    Object.assign(ui, patch);
    redraw();
  }
  function run(fn) {
    return update(s => fn(norm(s))).catch(() => false);
  }

  function start() {
    const task = String(ui.draft || '').trim().slice(0, 100);
    if (!task) {
      ui.err = '先写下这一轮要做什么';
      redraw();
      return;
    }
    ui.err = '';
    ui.notice = '';
    ui.confirm = false;
    run(s => {
      if (s.timer) return s;
      const total = s.settings.focusMin * 60;
      return Object.assign({}, s, {
        timer: { phase: 'focus', task: task, totalSec: total, status: 'running', endAt: Date.now() + total * 1000 }
      });
    }).then(ok => { if (ok) ui.draft = ''; });
  }

  function pause() {
    run(s => {
      const t = s.timer;
      if (!t || t.status !== 'running') return s;
      const rem = Math.max(0, Math.ceil((t.endAt - Date.now()) / 1000));
      return Object.assign({}, s, { timer: Object.assign({}, t, { status: 'paused', endAt: null, remainSec: rem }) });
    });
  }

  function resume() {
    run(s => {
      const t = s.timer;
      if (!t || t.status !== 'paused') return s;
      return Object.assign({}, s, {
        timer: Object.assign({}, t, { status: 'running', endAt: Date.now() + (t.remainSec || 0) * 1000, remainSec: null })
      });
    });
  }

  // 放弃专注需二次确认；休息可直接跳过
  function stopRound() {
    if (T && T.phase === 'focus' && !ui.confirm) {
      ui.confirm = true;
      redraw();
      return;
    }
    ui.confirm = false;
    ui.notice = T && T.phase === 'break' ? '已跳过休息，可以开始下一轮' : '上一轮已放弃，未计入完成';
    run(s => Object.assign({}, s, { timer: null }));
  }

  // 调整当前这一段（运行或暂停中）的剩余时间，每次 5 分钟，至少保留 1 分钟
  function adjust(dm) {
    run(s => {
      const t = s.timer;
      if (!t) return s;
      const now = Date.now();
      const left = leftSec(t, now);
      if (dm < 0 && left <= 60) return s;
      const nl = Math.min(180 * 60, Math.max(60, left + dm * 60));
      const nt = Object.assign({}, t, { totalSec: Math.max(60, t.totalSec + (nl - left)) });
      if (t.status === 'paused') nt.remainSec = Math.round(nl);
      else nt.endAt = now + nl * 1000;
      return Object.assign({}, s, { timer: nt });
    });
  }

  // 修改默认时长（用于之后的每一轮）
  function setSet(key, f) {
    const lim = key === 'focusMin' ? [1, 180] : [1, 60];
    return run(s => {
      const cur = s.settings[key];
      const v = clampInt(f(cur), lim[0], lim[1], cur);
      if (v === cur) return s;
      return Object.assign({}, s, { settings: Object.assign({}, s.settings, { [key]: v }) });
    });
  }

  // 到点结算：专注完成记一轮并自动进入休息；离开期间到点的也按结束时刻补记
  function settle() {
    if (ui.settling || Date.now() - (ui.settleFail || 0) < 5000) return;
    ui.settling = true;
    update(s0 => {
      const s = norm(s0);
      let t = s.timer;
      const now = Date.now();
      if (!t || t.status !== 'running' || now < t.endAt) return s;
      const rounds = s.rounds.slice();
      while (t && t.status === 'running' && now >= t.endAt) {
        if (t.phase === 'focus') {
          rounds.push({ id: uid(), task: t.task, minutes: Math.max(1, Math.round(t.totalSec / 60)), day: dayOf(t.endAt), doneAt: t.endAt });
          const bs = s.settings.breakMin * 60;
          t = { phase: 'break', task: t.task, totalSec: bs, status: 'running', endAt: t.endAt + bs * 1000 };
          ui.notice = '';
        } else {
          t = null;
          ui.notice = '休息结束，可以开始下一轮';
        }
      }
      return Object.assign({}, s, { timer: t, rounds: rounds });
    }).then(
      ok => { ui.settling = false; if (!ok) ui.settleFail = Date.now(); },
      () => { ui.settling = false; ui.settleFail = Date.now(); }
    );
  }

  function statusText() {
    if (!T) return '待开始';
    const n = T.phase === 'focus' ? '专注' : '休息';
    return T.status === 'paused' ? n + '已暂停' : n + '中';
  }


  function stepper(label, key, lo, hi) {
    return el('div', { class: 'row' },
      el('span', { class: 'lbl' }, label),
      el('div', { class: 'step' },
        el('button', { type: 'button', class: 'sb', 'aria-label': label + '时长减1分钟', onclick: () => setSet(key, c => c - 1) }, '−'),
        el('input', {
          class: 'num', type: 'number', min: String(lo), max: String(hi), step: '1',
          value: String(st[key]), 'aria-label': label + '时长（分钟）',
          onkeydown: e => { if (e.key === 'Enter') e.target.blur(); },
          onchange: e => { const x = e.target.value; setSet(key, () => x).then(() => redraw()); }
        }),
        el('button', { type: 'button', class: 'sb', 'aria-label': label + '时长加1分钟', onclick: () => setSet(key, c => c + 1) }, '+'),
        el('span', { class: 'unit' }, '分钟')));
  }

  function settingsPanel() {
    const kids = [
      el('div', { class: 'ptitle' }, '时长设置'),
      stepper('专注', 'focusMin', 1, 180),
      stepper('休息', 'breakMin', 1, 60)
    ];
    if (T) {
      kids.push(el('div', { class: 'row' },
        el('span', { class: 'lbl' }, '本段'),
        el('div', { class: 'step' },
          el('button', { type: 'button', class: 'sb wide', 'aria-label': '当前这一段减5分钟', onclick: () => adjust(-5) }, '−5'),
          el('button', { type: 'button', class: 'sb wide', 'aria-label': '当前这一段加5分钟', onclick: () => adjust(5) }, '+5'),
          el('span', { class: 'unit' }, '分钟'))));
      kids.push(el('div', { class: 'hint left' }, '上两行用于之后的轮次；「本段」只调整正在进行的这一段。'));
    } else {
      kids.push(el('div', { class: 'hint left' }, '修改后从下一轮开始生效。'));
    }
    return el('div', { class: 'sec set' }, ...kids);
  }

  function logPanel() {
    const head = el('div', { class: 'ptitle' }, '今日 ' + todays.length + ' 轮 · 共 ' + todayMin + ' 分钟');
    let body;
    if (todays.length) {
      body = el('div', { class: 'list' }, ...todays.map(r =>
        el('div', { class: 'li' },
          el('span', { class: 'lt' }, hhmm(r.doneAt)),
          el('span', { class: 'ln' }, r.task),
          el('span', { class: 'lm' }, r.minutes + ' 分'))));
    } else {
      body = el('div', { class: 'empty' }, '今天还没有完成的专注轮次');
    }
    return el('div', { class: 'sec log' }, head, body);
  }

  function subview(inner) {
    const kids = [
      el('button', { type: 'button', class: 'chip', 'aria-label': '返回计时', onclick: () => setUi({ view: 'main' }) }, '‹ 返回'),
      el('span', { class: 'pill' }, statusText()),
      el('span', { class: 'sp' })
    ];
    if (T) {
      timeEl = el('span', { class: 'mini' }, mmss(leftSec(T, Date.now())));
      kids.push(timeEl);
    }
    return el('div', { class: 'sub' }, el('div', { class: 'top' }, ...kids), inner);
  }

  function top() {
    const cnt = '今日 ' + todays.length + ' 轮';
    const kids = [el('span', { class: 'pill' }, statusText()), el('span', { class: 'sp' })];
    if (roomy) {
      kids.push(el('span', { class: 'stat' }, size === '6x6' ? cnt + ' · ' + todayMin + ' 分钟' : cnt));
    } else {
      kids.push(el('button', { type: 'button', class: 'chip', 'aria-label': '查看' + cnt + '的记录', onclick: () => setUi({ view: 'log' }) }, cnt));
      kids.push(el('button', { type: 'button', class: 'chip', 'aria-label': '修改时长', onclick: () => setUi({ view: 'settings' }) }, '时长'));
    }
    return el('div', { class: 'top' }, ...kids);
  }


  function ring() {
    const total = T ? Math.max(1, T.totalSec) : st.focusMin * 60;
    const left = T ? leftSec(T, Date.now()) : total;
    const p = T ? Math.min(100, Math.max(0, (1 - left / total) * 100)) : 0;
    const txt = mmss(left);
    ringEl = el('div', { class: 'ring' });
    ringEl.style.setProperty('--p', String(p));
    timeEl = el('div', { class: 'tm' + (txt.length > 5 ? ' long' : '') }, txt);
    return el('div', { class: 'ringwrap' }, ringEl, timeEl);
  }

  function panel() {
    if (!T) {
      const kids = [];
      if (ui.notice) kids.push(el('div', { class: 'notice' }, ui.notice));
      kids.push(el('input', {
        class: 'task', type: 'text', placeholder: '这一轮要做什么？', 'aria-label': '这一轮要做什么',
        value: ui.draft || '',
        oninput: e => {
          ui.draft = e.target.value;
          if (ui.err) { ui.err = ''; if (errEl) errEl.textContent = ''; }
        },
        onkeydown: e => { if (e.key === 'Enter' && !e.isComposing) start(); }
      }));
      errEl = el('div', { class: 'err' }, ui.err ? '！' + ui.err : '');
      kids.push(errEl);
      kids.push(el('button', { type: 'button', class: 'b primary', onclick: start }, '开始专注 ' + st.focusMin + ' 分钟'));
      kids.push(el('div', { class: 'hint' }, '休息 ' + st.breakMin + ' 分钟 · 可暂停、可改时长'));
      return el('div', { class: 'panel' }, ...kids);
    }
    const running = T.status === 'running';
    const lab = T.phase === 'focus' ? '正在做' : '休息一下 · 刚完成';
    return el('div', { class: 'panel' },
      el('div', { class: 'act' },
        el('div', { class: 'nowl' }, lab),
        el('div', { class: 'tk', title: T.task }, T.task)),
      el('div', { class: 'ctl' },
        el('button', { type: 'button', class: 'b primary', onclick: running ? pause : resume }, running ? '暂停' : '继续'),
        el('button', { type: 'button', class: 'b', onclick: stopRound },
          T.phase === 'break' ? '跳过休息' : (ui.confirm ? '确认放弃' : '放弃本轮'))));
  }

  const cls = ['ft', 's-' + size, T ? 'active' : 'idle'];
  if (T && T.phase === 'break') cls.push('isbreak');
  if (T && T.status === 'paused') cls.push('paused');
  let kids;
  if (view === 'settings') kids = [subview(settingsPanel())];
  else if (view === 'log') kids = [subview(logPanel())];
  else {
    kids = [top(), el('div', { class: 'main' }, ring(), panel())];
    if (roomy) kids.push(el('div', { class: 'extra' }, settingsPanel(), logPanel()));
  }
  root.appendChild(el('div', { class: cls.join(' ') }, ...kids));

  // 每秒刷新倒计时文字与进度环（不重绘，输入框不会丢焦点）；到点触发结算
  function tick() {
    if (day() !== today) { redraw(); return; }
    if (!T || T.status !== 'running') return;
    const left = leftSec(T, Date.now());
    if (timeEl) timeEl.textContent = mmss(left);
    if (ringEl) ringEl.style.setProperty('--p', String(Math.min(100, Math.max(0, (1 - left / Math.max(1, T.totalSec)) * 100))));
    if (left <= 0) settle();
  }
  iv = setInterval(tick, 1000);
  t0 = setTimeout(tick, 0);
  if (ui.confirm) ct = setTimeout(() => { ui.confirm = false; redraw(); }, 4000);

  return function () {
    if (iv) clearInterval(iv);
    if (t0) clearTimeout(t0);
    if (ct) clearTimeout(ct);
  };
